//! Static game data (names, icons, recipes, masterable items, relics, drop
//! sources, market slugs) generated by `scripts/gen_catalog.py` from Warframe's
//! official Public Export, the WFCD drop tables and warframe.market.

use crate::util::{blueprint_form, component_form};
use serde::Deserialize;
use std::collections::HashMap;
use std::io::Read;

pub struct Part {
    pub unique: String,
    pub name: String,
    /// How many copies the recipe needs.
    pub need: u32,
}

pub struct Prime {
    pub unique: String,
    pub name: String,
    /// XP at which the item counts as mastered (weapons 450k, frames 900k).
    pub mastery_xp: u64,
    pub parts: Vec<Part>,
}

#[derive(Clone)]
pub struct Recipe {
    pub result: String,
    pub blueprint: String,
    pub credits: u64,
    pub secs: u64,
    pub num: u32,
    pub ingredients: Vec<(String, u64)>,
}

#[derive(Clone)]
pub struct Item {
    pub unique: String,
    pub name: String,
    pub category: String,
    pub mr: u32,
    pub mastery_xp: u64,
}

#[derive(Clone)]
pub struct RelicReward {
    pub unique: String,
    pub rarity: String,
    pub count: u32,
}

#[derive(Clone)]
pub struct Relic {
    /// e.g. `Axi A17`
    pub name: String,
    pub era: String,
    pub rewards: Vec<RelicReward>,
}

#[derive(Clone)]
pub struct Drop {
    pub place: String,
    pub rarity: char,
    pub chance: f32,
}

#[derive(Deserialize)]
struct RawPrime {
    u: String,
    n: String,
    x: u64,
    p: Vec<(String, String, u32)>,
}

#[derive(Deserialize)]
struct RawRecipe {
    r: String,
    b: String,
    #[serde(default)]
    c: u64,
    #[serde(default)]
    t: u64,
    #[serde(default)]
    n: u32,
    #[serde(default)]
    i: Vec<(String, u64)>,
}

#[derive(Deserialize)]
struct RawItem {
    u: String,
    n: String,
    #[serde(default)]
    c: String,
    #[serde(default)]
    m: u32,
    #[serde(default)]
    x: u64,
}

#[derive(Deserialize)]
struct RawRelic {
    n: String,
    rw: Vec<(String, String, u32)>,
}

#[derive(Deserialize)]
struct Raw {
    names: HashMap<String, String>,
    icons: HashMap<String, String>,
    primes: Vec<RawPrime>,
    #[serde(default)]
    recipes: HashMap<String, RawRecipe>,
    #[serde(default)]
    items: Vec<RawItem>,
    #[serde(default)]
    relics: HashMap<String, RawRelic>,
    #[serde(default)]
    res: HashMap<String, String>,
    #[serde(default)]
    slugs: HashMap<String, String>,
    #[serde(default)]
    drops: HashMap<String, Vec<(String, String, f32)>>,
}

pub const REFINEMENTS: [(&str, &str); 4] =
    [("Bronze", "Intact"), ("Silver", "Exceptional"), ("Gold", "Flawless"), ("Platinum", "Radiant")];

pub struct Catalog {
    /// lowercase unique path -> display name
    names: HashMap<String, String>,
    /// lowercase unique path -> icon texture location
    icons: HashMap<String, String>,
    pub primes: Vec<Prime>,
    /// lowercase result path -> recipe
    recipes: HashMap<String, Recipe>,
    /// lowercase blueprint path -> lowercase result path
    by_blueprint: HashMap<String, String>,
    pub items: Vec<Item>,
    item_index: HashMap<String, usize>,
    /// lowercase relic base path -> relic
    relics: HashMap<String, Relic>,
    /// lowercase reward path -> [(lowercase relic base path, rarity)]
    reward_index: HashMap<String, Vec<(String, String)>>,
    res: HashMap<String, String>,
    slugs: HashMap<String, String>,
    drops: HashMap<String, Vec<Drop>>,
    /// (lowercase display name, lowercase unique path), for searching.
    name_list: Vec<(String, String)>,
}

impl Catalog {
    pub fn load() -> Self {
        let gz = include_bytes!("../assets/catalog.json.gz");
        let mut json = String::new();
        flate2::read::GzDecoder::new(&gz[..]).read_to_string(&mut json).expect("bundled catalog decompresses");
        Self::from_json(&json).expect("bundled catalog is valid")
    }

    pub fn from_json(s: &str) -> Result<Self, serde_json::Error> {
        let raw: Raw = serde_json::from_str(s)?;
        let primes = raw
            .primes
            .into_iter()
            .map(|p| Prime {
                unique: p.u,
                name: p.n,
                mastery_xp: p.x,
                parts: p.p.into_iter().map(|(unique, name, need)| Part { unique, name, need }).collect(),
            })
            .collect();

        let mut recipes = HashMap::new();
        let mut by_blueprint = HashMap::new();
        for (k, r) in raw.recipes {
            by_blueprint.insert(r.b.to_lowercase(), k.clone());
            recipes.insert(
                k,
                Recipe { result: r.r, blueprint: r.b, credits: r.c, secs: r.t, num: r.n.max(1), ingredients: r.i },
            );
        }

        let items: Vec<Item> = raw
            .items
            .into_iter()
            .map(|i| Item { unique: i.u, name: i.n, category: i.c, mr: i.m, mastery_xp: i.x })
            .collect();
        let item_index = items.iter().enumerate().map(|(i, it)| (it.unique.to_lowercase(), i)).collect();

        let mut reward_index: HashMap<String, Vec<(String, String)>> = HashMap::new();
        let mut relics = HashMap::new();
        for (k, r) in raw.relics {
            let era = r.n.split_whitespace().next().unwrap_or("").to_string();
            let rewards: Vec<RelicReward> = r
                .rw
                .into_iter()
                .map(|(unique, rarity, count)| RelicReward { unique, rarity, count })
                .collect();
            for rw in &rewards {
                reward_index.entry(rw.unique.to_lowercase()).or_default().push((k.clone(), rw.rarity.clone()));
            }
            relics.insert(k, Relic { name: r.n, era, rewards });
        }

        let drops = raw
            .drops
            .into_iter()
            .map(|(k, v)| {
                let v = v
                    .into_iter()
                    .map(|(place, rarity, chance)| Drop { place, rarity: rarity.chars().next().unwrap_or('?'), chance })
                    .collect();
                (k, v)
            })
            .collect();

        let name_list = raw.names.iter().map(|(u, n)| (n.to_lowercase(), u.clone())).collect();

        Ok(Self {
            names: raw.names,
            icons: raw.icons,
            primes,
            recipes,
            by_blueprint,
            items,
            item_index,
            relics,
            reward_index,
            res: raw.res,
            slugs: raw.slugs,
            drops,
            name_list,
        })
    }

    pub fn name(&self, unique: &str) -> Option<&str> {
        self.names.get(&unique.to_lowercase()).map(String::as_str)
    }

    /// Display name with a readable fallback derived from the path.
    pub fn display(&self, unique: &str) -> String {
        if let Some(n) = self.name(unique) {
            return n.to_string();
        }
        // A built component shares its name with the blueprint minus the suffix.
        if let Some(n) = self.name(&blueprint_form(unique)) {
            return n.trim_end_matches(" Blueprint").to_string();
        }
        crate::compare::pretty_name(unique)
    }

    pub fn icon(&self, unique: &str) -> Option<&str> {
        let l = unique.to_lowercase();
        if let Some(i) = self.icons.get(&l) {
            return Some(i.as_str());
        }
        // components and blueprints share a picture
        self.icons.get(&component_form(&l)).or_else(|| self.icons.get(&blueprint_form(&l))).map(String::as_str)
    }

    pub fn recipe(&self, result: &str) -> Option<&Recipe> {
        self.recipes.get(&result.to_lowercase())
    }

    /// The item a blueprint produces.
    pub fn result_of_blueprint(&self, blueprint: &str) -> Option<&str> {
        let key = self.by_blueprint.get(&blueprint.to_lowercase())?;
        self.recipes.get(key).map(|r| r.result.as_str())
    }

    pub fn item(&self, unique: &str) -> Option<&Item> {
        self.item_index.get(&unique.to_lowercase()).map(|&i| &self.items[i])
    }

    /// Best match for a typed name. Exact names win, then prime items, then the
    /// shortest name that contains the query.
    pub fn find_item(&self, query: &str) -> Option<&Item> {
        let q = query.trim().to_lowercase();
        if q.is_empty() {
            return None;
        }
        if let Some(it) = self.items.iter().find(|i| i.name.to_lowercase() == q) {
            return Some(it);
        }
        let mut hits: Vec<&Item> = self.items.iter().filter(|i| i.name.to_lowercase().contains(&q)).collect();
        hits.sort_by_key(|i| (!i.name.contains("Prime"), i.name.len()));
        hits.into_iter().next()
    }

    /// The masterable item whose name appears in `text` (longest name wins).
    pub fn mentioned_item(&self, text: &str) -> Option<&Item> {
        let t = text.to_lowercase();
        self.items.iter().filter(|i| i.name.len() >= 3 && t.contains(&i.name.to_lowercase())).max_by_key(|i| i.name.len())
    }

    /// Any named thing (parts, resources, mods...). Returns (lowercase unique, name).
    pub fn search_names(&self, query: &str, limit: usize) -> Vec<(String, String)> {
        let q = query.trim().to_lowercase();
        if q.len() < 2 {
            return vec![];
        }
        let mut hits: Vec<&(String, String)> = self.name_list.iter().filter(|(n, _)| n.contains(&q)).collect();
        hits.sort_by_key(|(n, _)| (n != &q, n.len()));
        hits.into_iter().take(limit).map(|(_, u)| (u.clone(), self.names[u].clone())).collect()
    }

    /// Names that appear inside free text, longest first: (lowercase unique, name).
    pub fn mentioned(&self, text: &str, limit: usize) -> Vec<(String, String)> {
        let t = text.to_lowercase();
        let mut hits: Vec<&(String, String)> = self.name_list.iter().filter(|(n, _)| n.len() >= 4 && t.contains(n.as_str())).collect();
        hits.sort_by(|a, b| b.0.len().cmp(&a.0.len()).then(a.0.cmp(&b.0)));
        let mut out: Vec<(String, String)> = Vec::new();
        for (_, u) in hits {
            let name = self.names[u].clone();
            // skip names swallowed by a longer match ("Wisp" inside "Wisp Prime Systems")
            if out.iter().any(|(_, n)| n.to_lowercase().contains(&name.to_lowercase())) {
                continue;
            }
            out.push((u.clone(), name));
            if out.len() >= limit {
                break;
            }
        }
        out
    }

    pub fn slug(&self, unique: &str) -> Option<&str> {
        let l = unique.to_lowercase();
        self.slugs
            .get(&l)
            .or_else(|| self.slugs.get(&blueprint_form(&l)))
            .or_else(|| self.slugs.get(&component_form(&l)))
            .map(String::as_str)
    }

    pub fn resource_hint(&self, unique: &str) -> Option<&str> {
        self.res.get(&unique.to_lowercase()).map(String::as_str)
    }

    /// Non-relic places an item (by display name) drops from, best chance first.
    pub fn drops_for(&self, display_name: &str) -> Vec<&Drop> {
        let mut v: Vec<&Drop> = self.drops.get(display_name).map(|d| d.iter().collect()).unwrap_or_default();
        v.sort_by(|a, b| b.chance.partial_cmp(&a.chance).unwrap_or(std::cmp::Ordering::Equal));
        v
    }

    /// `(relic, refinement name)` for an inventory relic path like `...T4VoidProjectionXPrimeASilver`.
    pub fn relic(&self, inventory_unique: &str) -> Option<(&Relic, &'static str)> {
        let l = inventory_unique.to_lowercase();
        for (suffix, label) in REFINEMENTS {
            if let Some(base) = l.strip_suffix(&suffix.to_lowercase()) {
                if let Some(r) = self.relics.get(base) {
                    return Some((r, label));
                }
            }
        }
        None
    }

    /// Relics (by base path) that can drop a part, with the part's rarity there.
    pub fn relics_with(&self, reward_unique: &str) -> Vec<(&Relic, &str)> {
        let l = reward_unique.to_lowercase();
        let mut out = Vec::new();
        for key in [l.clone(), blueprint_form(&l), component_form(&l)] {
            if let Some(v) = self.reward_index.get(&key) {
                for (base, rarity) in v {
                    if let Some(r) = self.relics.get(base) {
                        if !out.iter().any(|(x, _): &(&Relic, &str)| std::ptr::eq(*x, r)) {
                            out.push((r, rarity.as_str()));
                        }
                    }
                }
            }
        }
        out
    }

    pub fn relic_count(&self) -> usize {
        self.relics.len()
    }
}

#[cfg(test)]
pub fn test_catalog() -> Catalog {
    Catalog::from_json(
        r#"{"names":{"/lotus/types/recipes/warframerecipes/wispprimesystemsblueprint":"Wisp Prime Systems Blueprint",
            "/lotus/types/recipes/warframerecipes/wispprimesystemscomponent":"Wisp Prime Systems",
            "/lotus/types/items/miscitems/ferrite":"Ferrite"},
           "icons":{},"primes":[],
           "recipes":{
             "/lotus/powersuits/wisp/wispprime":{"r":"/Lotus/Powersuits/Wisp/WispPrime","b":"/Lotus/Types/Recipes/WarframeRecipes/WispPrimeBlueprint","c":25000,"t":259200,"n":1,
               "i":[["/Lotus/Types/Recipes/WarframeRecipes/WispPrimeSystemsComponent",1],["/Lotus/Types/Items/MiscItems/OrokinCell",5]]},
             "/lotus/types/recipes/warframerecipes/wispprimesystemscomponent":{"r":"/Lotus/Types/Recipes/WarframeRecipes/WispPrimeSystemsComponent","b":"/Lotus/Types/Recipes/WarframeRecipes/WispPrimeSystemsBlueprint","c":15000,"t":43200,"n":1,
               "i":[["/Lotus/Types/Items/MiscItems/Ferrite",100],["/Lotus/Types/Items/MiscItems/Circuits",50]]}},
           "items":[{"u":"/Lotus/Powersuits/Wisp/WispPrime","n":"Wisp Prime","c":"Suits","m":0,"x":900000}],
           "relics":{"/lotus/types/game/projections/t4voidprojectionwispprimea":{"n":"Axi W1","rw":[["/Lotus/Types/Recipes/WarframeRecipes/WispPrimeSystemsBlueprint","uncommon",1]]}},
           "slugs":{"/lotus/types/recipes/warframerecipes/wispprimesystemsblueprint":"wisp_prime_systems_blueprint"}}"#,
    )
    .unwrap()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lookups() {
        let c = test_catalog();
        assert_eq!(c.find_item("wisp").unwrap().name, "Wisp Prime");
        assert!(c.recipe("/Lotus/Powersuits/Wisp/WispPrime").is_some());
        assert_eq!(
            c.result_of_blueprint("/Lotus/Types/Recipes/WarframeRecipes/WispPrimeSystemsBlueprint"),
            Some("/Lotus/Types/Recipes/WarframeRecipes/WispPrimeSystemsComponent")
        );
        // component path finds the blueprint's slug and relics
        let comp = "/Lotus/Types/Recipes/WarframeRecipes/WispPrimeSystemsComponent";
        assert_eq!(c.slug(comp), Some("wisp_prime_systems_blueprint"));
        assert_eq!(c.relics_with(comp).len(), 1);
        let (r, label) = c.relic("/Lotus/Types/Game/Projections/T4VoidProjectionWispPrimeAGold").unwrap();
        assert_eq!((r.name.as_str(), label), ("Axi W1", "Flawless"));
        assert_eq!(c.display(comp), "Wisp Prime Systems");
    }
}
